// src/infrastructure/rl/networkMappoPolicyFixture.spec.ts
//
// The **transfer check** for the multi-junction signal policy.
//
// The weights the MAPPO trainer produces must be interpretable by the
// browser: the same weights and the same observation must give the same
// action index in Python and in the browser. The policy is
// **parameter-shared** - one actor serves every junction - so the browser
// runs it per junction, which is what its policy source does.
//
// The fixture is generated by the backend (it owns the training side):
//   cd TraffSim3D-backend
//   .\.venv\Scripts\python.exe scripts\gen_network_mappo_fixture.py
// It holds the exported weights of the 5 x 5 grid policy trained by
// `app.apps.rl.network_mappo`, the observations, and the action index each
// observation must produce (computed twice on the Python side: by the
// trainer's own actor and by a pure-Python reference implementation).

import { describe, it, expect } from 'vitest'
import fixture from './fixtures/network-mappo-policy-fixture.json'
import { mlpForwardDiscrete } from './mlpInference'
import type { PolicyWeights } from './types'
import { SIGNAL_ACTION_NAMES } from '@shared/constants/simulation'

const POLICY: PolicyWeights = {
  name: fixture.name,
  obs_dim: fixture.obs_dim,
  action_dim: fixture.action_dim,
  action_space: fixture.action_space as PolicyWeights['action_space'],
  hidden_sizes: fixture.hidden_sizes,
  layers: fixture.layers as PolicyWeights['layers'],
}

const OBSERVATIONS = fixture.observations as number[][]
const EXPECTED = fixture.expected_actions as number[]
const EXPECTED_NAMES = fixture.expected_action_names as string[]

describe('the network signal policy transfer check', () => {
  it('is a discrete five-action policy with no Gaussian log-std', () => {
    expect(POLICY.action_space).toBe('discrete')
    expect(POLICY.action_dim).toBe(5)
    expect(POLICY.obs_dim).toBe(6)
    // A discrete policy has no `log_std` - the export omits the key.
    expect(POLICY.layers.log_std).toBeUndefined()
  })

  it('has the layer layout the browser hard-codes', () => {
    // `mlpInference` reads these keys by name: `policy_net.0` and
    // `policy_net.2` are the two Tanh layers, `action_net` is the logits.
    expect(POLICY.hidden_sizes).toEqual([64, 64])
    expect(POLICY.layers['policy_net.0.weight']).toHaveLength(64)
    expect(POLICY.layers['policy_net.0.weight'][0]).toHaveLength(6)
    expect(POLICY.layers['policy_net.2.weight']).toHaveLength(64)
    expect(POLICY.layers['policy_net.2.weight'][0]).toHaveLength(64)
    expect(POLICY.layers['action_net.weight']).toHaveLength(5)
    expect(POLICY.layers['action_net.weight'][0]).toHaveLength(64)
  })

  it('the browser reproduces the Python action for every committed observation', () => {
    expect(OBSERVATIONS).toHaveLength(EXPECTED.length)
    OBSERVATIONS.forEach((obs, i) => {
      expect(mlpForwardDiscrete(obs, POLICY)).toBe(EXPECTED[i])
    })
  })

  it('the action index maps to the shared five-action vocabulary', () => {
    // The index is the position in `sim_core.SIGNAL_ACTION_NAMES` - a
    // cross-language contract, not a browser-local ordering.
    expect(fixture.action_names).toEqual([...SIGNAL_ACTION_NAMES])
    EXPECTED.forEach((index, i) => {
      expect(SIGNAL_ACTION_NAMES[index]).toBe(EXPECTED_NAMES[i])
    })
  })

  it('every observation has the six dimensions of the signal schema', () => {
    for (const obs of OBSERVATIONS) {
      expect(obs).toHaveLength(6)
      // The two queue lengths and the phase clock are normalised; the
      // phase clock may be negative (extend_green pushes it below zero).
      expect(obs[0]).toBeGreaterThanOrEqual(0)
      expect(obs[0]).toBeLessThanOrEqual(1)
      expect(obs[1]).toBeGreaterThanOrEqual(0)
      expect(obs[1]).toBeLessThanOrEqual(1)
      expect([0, 1]).toContain(obs[2])
      expect([0, 1]).toContain(obs[3])
      expect([0, 1]).toContain(obs[4])
      expect(obs[5]).toBeGreaterThanOrEqual(-1)
      expect(obs[5]).toBeLessThanOrEqual(1)
    }
  })

  it('the fixture is not satisfied by a constant action', () => {
    // Otherwise the forward pass could always return the same index.
    expect(new Set(EXPECTED).size).toBeGreaterThan(1)
  })

  it('the policy is the one that beat the fixed cycle', () => {
    // The training run's own numbers, committed with the weights: the
    // network total delay against the `no_op` baseline on the held-out
    // seeds. The browser measures the same quantity on its own grid.
    const training = fixture.training as {
      margin: number
      beats_baseline: boolean
      env_steps: number
    }
    expect(training.beats_baseline).toBe(true)
    expect(training.margin).toBeGreaterThan(0)
    expect(training.env_steps).toBeGreaterThan(0)
  })
})
